#!/usr/bin/env bash
# PreToolUse guard: refuse any Bash command that runs rm with both recursive
# and force flags (rm -rf and its spellings). Reads the event JSON on stdin.
# Exit 2 blocks the call and sends the stderr message back to Claude.
set -u

exec python3 -I - <<'PY'
import json
import re
import shlex
import sys

BLOCK = "Blocked: `rm -rf` is not allowed in this project. Delete specific paths with an explicit, non-recursive command, or ask the user to run it."

try:
    event = json.load(sys.stdin)
    command = event.get("tool_input", {}).get("command", "")
except (ValueError, AttributeError):
    # Unreadable event: fail closed rather than let a possible rm -rf through.
    print(BLOCK + " (could not parse hook input)", file=sys.stderr)
    sys.exit(2)

def is_rm_rf(segment):
    try:
        tokens = shlex.split(segment)
    except ValueError:
        tokens = segment.split()
    for i, tok in enumerate(tokens):
        if tok != "rm" and not tok.endswith("/rm"):
            continue
        recursive = force = False
        for arg in tokens[i + 1:]:
            if arg == "--":
                break
            if arg == "--recursive":
                recursive = True
            elif arg == "--force":
                force = True
            elif arg.startswith("-") and not arg.startswith("--"):
                recursive |= "r" in arg or "R" in arg
                force |= "f" in arg
        if recursive and force:
            return True
    return False

# Split on shell command separators so `cd x && rm -rf y` and `xargs rm -rf` are caught.
segments = re.split(r"[;&|\n(){}`]|\$\(", command)
if any(is_rm_rf(s) for s in segments):
    print(BLOCK, file=sys.stderr)
    sys.exit(2)
sys.exit(0)
