content:
#!/usr/bin/env bash
# PreToolUse hook: block `rm` runs that combine recursive and force (rm -rf and its variants).
# Reads the hook event JSON on stdin. Exit 2 blocks the Bash call; stderr is shown to Claude.
exec python3 -I -c '
import json, os, re, shlex, sys

def is_rm_rf(cmd):
    for seg in re.split(r"[;&|\n()`]+", cmd):
        try:
            toks = shlex.split(seg)
        except ValueError:
            toks = seg.split()
        # Nested command strings, e.g. bash -c "rm -rf x" or sudo sh -c "...".
        for tok in toks:
            if " " in tok or ";" in tok or "\n" in tok:
                if is_rm_rf(tok):
                    return True
        for i, tok in enumerate(toks):
            if os.path.basename(tok) != "rm":
                continue
            args = []
            for a in toks[i + 1:]:
                if a == "--":
                    break
                if a.startswith("-"):
                    args.append(a)
            short = "".join(a[1:] for a in args if not a.startswith("--"))
            longs = [a for a in args if a.startswith("--")]
            recursive = any(c in short for c in "rR") or "--recursive" in longs
            force = "f" in short or "--force" in longs
            if recursive and force:
                return True
    return False

try:
    cmd = json.load(sys.stdin).get("tool_input", {}).get("command", "")
except Exception:
    sys.stderr.write("block-rm: could not read hook input; blocking to be safe.\n")
    sys.exit(2)

if is_rm_rf(cmd):
    sys.stderr.write("Blocked: rm -rf is not allowed in this project. Delete the specific files by name instead, or ask the user to run it.\n")
    sys.exit(2)
'

